<?php
declare(strict_types=1);
require_once __DIR__.'/includes/bootstrap.php';

function lh_lesson_page(PDO $db,string $slug,int $id=0): ?array {
    $hasCh=false;$hasSlug=false;$hasCourse=false;$hasContent=false;
    try { $q=$db->query("SELECT column_name FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='learning_lessons'"); foreach($q->fetchAll(PDO::FETCH_COLUMN) as $c){$hasCh|=$c==='chapter_id';$hasSlug|=$c==='slug';$hasCourse|=$c==='course_id';$hasContent|=$c==='content';} } catch(Throwable) {}
    if(!$hasSlug) return null;
    $params=[];$where='l.slug=?';$params[]=$slug;
    if($id>0){$where='l.id=?';$params=[$id];}
    $sql="SELECT l.*";
    if($hasCh) $sql .= ",ch.title chapter_title,ch.course_id chapter_course_id";
    $sql .= ",$where";
    if($hasCh) $sql .= " AND EXISTS(SELECT 1 FROM learning_chapters ch2 WHERE ch2.id=l.chapter_id)";
    if($hasCourse) $sql .= " LIMIT 1";
    try{$q=$db->prepare(str_replace(',',$sql[0]===','?'':',',$sql));}catch(Throwable){$q=null;}
    if($q){try{$q->execute($params);$r=$q->fetch(PDO::FETCH_ASSOC);if($r)return $r;}catch(Throwable){} }
    $sql='SELECT l.* FROM learning_lessons l WHERE '.$where.' LIMIT 1';
    try{$q=$db->prepare($sql);$q->execute($params);return $q->fetch(PDO::FETCH_ASSOC)?:null;}catch(Throwable){return null;}
}

$slug=trim((string)($_GET['slug']??''));$id=(int)($_GET['id']??0);$lesson=$slug?lh_lesson_page($db,$slug,$id):($id?lh_lesson_page($db,'',$id):null);
if(!$lesson){http_response_code(404);$lh_page_title='Lesson not found';$lh_description='The requested lesson could not be found.';include __DIR__.'/includes/header.php';include __DIR__.'/includes/navbar.php';?><main class="container py-5"><div class="lh-empty p-5 text-center"><div class="fs-1">📚</div><h1 class="h4 mt-3">Lesson not found</h1><p class="text-secondary">This lesson may have been moved or unpublished.</p><a class="btn btn-primary" href="/learning-hub/courses.php">Browse Courses</a></div></main><?php include __DIR__.'/includes/footer.php';exit;}

$course=null;$courseId=(int)($lesson['course_id']??$lesson['chapter_course_id']??0);
if($courseId>0){try{$q=$db->prepare("SELECT c.*,lc.name category_name,lc.icon category_icon,lc.slug category_slug FROM learning_courses c LEFT JOIN learning_categories lc ON lc.id=c.category_id WHERE c.id=? LIMIT 1");$q->execute([$courseId]);$course=$q->fetch(PDO::FETCH_ASSOC)?:null;}catch(Throwable){}}
if(!$course&&$slug){try{$q=$db->prepare("SELECT c.*,lc.name category_name,lc.icon category_icon,lc.slug category_slug FROM learning_lessons l JOIN learning_chapters ch ON ch.id=l.chapter_id JOIN learning_courses c ON c.id=ch.course_id LEFT JOIN learning_categories lc ON lc.id=c.category_id WHERE l.slug=? LIMIT 1");$q->execute([$slug]);$course=$q->fetch(PDO::FETCH_ASSOC)?:null;}catch(Throwable){}}
if(!$course&&$courseId===0){http_response_code(404);exit('Course not found.');}
$courseId=(int)$course['id'];$lessonList=[];$navPos=0;$previous=null;$next=null;
try{$hasCh=(bool)$db->query("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='learning_lessons' AND column_name='chapter_id'")->fetchColumn();if($hasCh){$q=$db->prepare("SELECT l.id,l.title,l.slug,ch.title chapter_title FROM learning_lessons l JOIN learning_chapters ch ON ch.id=l.chapter_id WHERE ch.course_id=? AND l.enabled=1 ORDER BY ch.sort_order,ch.id,l.sort_order,l.id");$q->execute([$courseId]);}else{$q=$db->prepare("SELECT l.id,l.title,l.slug,'' chapter_title FROM learning_lessons l WHERE l.course_id=? AND l.enabled=1 ORDER BY l.sort_order,l.id");$q->execute([$courseId]);}$lessonList=$q->fetchAll(PDO::FETCH_ASSOC);foreach($lessonList as $i=>$item){if((int)$item['id']===(int)$lesson['id']){$navPos=$i+1;$previous=$lessonList[$i-1]??null;$next=$lessonList[$i+1]??null;break;}}}catch(Throwable){}
$done=false;$user=lh_user();if($user){try{$q=$db->prepare('SELECT completed FROM learning_progress WHERE user_id=? AND lesson_id=? LIMIT 1');$q->execute([(int)$user['id'],(int)$lesson['id']]);$done=(bool)$q->fetchColumn();}catch(Throwable){}}
if($_SERVER['REQUEST_METHOD']==='POST'&&$user){try{$q=$db->prepare('INSERT INTO learning_progress(user_id,lesson_id,completed,progress_percent) VALUES(?,?,1,100) ON DUPLICATE KEY UPDATE completed=1,progress_percent=100');$q->execute([(int)$user['id'],(int)$lesson['id']);$done=true;}catch(Throwable){}}
$lh_page_title=(string)$lesson['title'];$lh_description='Learn '.(string)$lesson['title'].' in the SmartToolz Learning Hub.';include __DIR__.'/includes/header.php';include __DIR__.'/includes/navbar.php';?><link rel="stylesheet" href="/learning-hub/assets/css/lesson.css"><div class="container-fluid"><div class="row"><div class="col-lg-3 col-xl-2 p-0"><?php include __DIR__.'/includes/sidebar.php';?></div><main class="col-lg-9 col-xl-10 py-4 py-lg-5"><div class="container-fluid"><div class="lh-lesson-layout"><aside class="lh-lesson-nav"><div class="fw-bold mb-2">Course lessons</div><?php foreach($lessonList as $item):?><a class="<?=((int)$item['id']===(int)$lesson['id'])?'active':''?>" href="/learning-hub/lesson.php?slug=<?=rawurlencode((string)$item['slug'])?>" data-spa><?=lh_h($item['title'])?></a><?php endforeach;?></aside><section class="lh-lesson-main"><div class="d-flex justify-content-between small mb-3"><a href="/learning-hub/course.php?slug=<?=rawurlencode((string)$course['slug'])?>" class="text-primary text-decoration-none" data-spa>← <?=lh_h($course['title'])?></a><span class="text-secondary">Lesson <?=number_format($navPos)?> / <?=number_format(count($lessonList))?></span></div><div class="progress lh-progress mb-4"><div class="progress-bar" style="width:<?=count($lessonList)?round(($navPos/count($lessonList))*100):0?>%"></div></div><article class="lh-card p-4 p-md-5"><span class="badge text-bg-primary mb-3"><?=lh_h($course['category_name']??'Learning Hub')?></span><h1 class="display-6 fw-bold"><?=lh_h($lesson['title'])?></h1><div class="lh-prose mt-4"><?=($lesson['content']??'')?:'<p class="text-secondary">Lesson content is being prepared.</p>'?></div><?php if($user):?><form method="post" class="mt-4"><button class="btn <?= $done?'btn-success':'btn-primary'?>" type="submit"><?= $done?'✓ Lesson completed':'Mark lesson complete'?></button></form><?php else:?><div class="alert alert-light border mt-4">Login to save your learning progress.</div><?php endif;?></article><div class="lh-next mt-4 p-3 d-flex justify-content-between gap-2"><a class="btn btn-outline-primary <?=empty($previous)?'disabled':''?>" href="<?=empty($previous)?'#':'/learning-hub/lesson.php?slug='.rawurlencode($previous['slug'])?>" data-spa>← Previous</a><a class="btn btn-primary <?=empty($next)?'disabled':''?>" href="<?=empty($next)?'#':'/learning-hub/lesson.php?slug='.rawurlencode($next['slug'])?>" data-spa><?=empty($next)?'Course Complete':'Next Lesson →'?></a></div><div class="lh-ad-slot my-4">Advertisement</div></section></div></div></main></div></div><?php include __DIR__.'/includes/footer.php';?><script src="/learning-hub/assets/js/app.js"></script><script src="/learning-hub/assets/js/router.js"></script>